package com.logatron.investigation.infrastructure;
import com.fasterxml.jackson.databind.*;import com.logatron.auth.application.EffectiveScope;import com.logatron.investigation.application.InvestigationPorts.MetricQueryPort;import com.logatron.investigation.configuration.InvestigationProperties;import com.logatron.investigation.domain.InvestigationModels.*;import org.springframework.stereotype.Component;import java.net.*;import java.net.http.*;import java.time.*;import java.util.*;
@Component public class PrometheusMetricQueryAdapter implements MetricQueryPort {
 private static final Map<MetricOperation,String> ALLOWLIST=Map.of(MetricOperation.DB_POOL_USAGE_RATIO,"max(hikaricp_connections_active{project_id=\"%s\"%s}) / clamp_min(max(hikaricp_connections_max{project_id=\"%s\"%s}),1)",MetricOperation.KAFKA_CONSUMER_LAG,"max(kafka_consumer_fetch_manager_records_lag{project_id=\"%s\"%s})",MetricOperation.HTTP_ERROR_RATE,"sum(rate(http_server_requests_seconds_count{project_id=\"%s\",status=~\"5..\"%s}[2m]))",MetricOperation.HTTP_LATENCY_P95,"histogram_quantile(0.95,sum by(le)(rate(http_server_requests_seconds_bucket{project_id=\"%s\"%s}[2m])))",MetricOperation.PROCESSOR_FAILURE_RATE,"sum(rate(logatron_processor_clickhouse_failures_total{project_id=\"%s\"%s}[2m]))",MetricOperation.PLATFORM_API_ERROR_RATE,"sum(rate(http_server_requests_seconds_count{application=\"log-a-tron-platform-api\",status=~\"5..\"}[2m]))");
 private final InvestigationProperties props;private final ObjectMapper mapper;private final HttpClient client;public PrometheusMetricQueryAdapter(InvestigationProperties p,ObjectMapper m){props=p;mapper=m;client=HttpClient.newBuilder().connectTimeout(p.metricTimeout()).build();}
 public List<MetricSeries> query(EffectiveScope scope,InvestigationQuery q,Set<MetricOperation> operations){if(!scope.projects().containsKey(q.projectId()))return List.of();List<MetricSeries> out=new ArrayList<>();for(MetricOperation op:operations){String template=ALLOWLIST.get(op);if(template==null)continue;String env=q.environmentId()==null?"":",environment_id=\""+q.environmentId()+"\"";String promql=template.formatted(q.projectId(),env,q.projectId(),env);try{String url=strip(props.prometheusUrl())+"/api/v1/query_range?query="+URLEncoder.encode(promql,java.nio.charset.StandardCharsets.UTF_8)+"&start="+q.from().getEpochSecond()+"&end="+q.to().getEpochSecond()+"&step=15";var response=client.send(HttpRequest.newBuilder(URI.create(url)).timeout(props.metricTimeout()).GET().build(),HttpResponse.BodyHandlers.ofString());if(response.statusCode()!=200)continue;JsonNode results=mapper.readTree(response.body()).path("data").path("result");if(!results.isArray())continue;for(JsonNode result:results){List<MetricPoint> points=new ArrayList<>();for(JsonNode pair:result.path("values"))points.add(new MetricPoint(Instant.ofEpochSecond(pair.get(0).asLong()),Double.parseDouble(pair.get(1).asText())));String service=result.path("metric").path("service").asText(result.path("metric").path("job").asText("platform"));out.add(new MetricSeries(op,service,unit(op),List.copyOf(points),"promql:"+op.name()+":"+q.from()+":"+q.to()));}}catch(Exception ignored){}}return List.copyOf(out);}
 private static String strip(String s){return s.endsWith("/")?s.substring(0,s.length()-1):s;}private static String unit(MetricOperation op){return switch(op){case DB_POOL_USAGE_RATIO->"ratio";case KAFKA_CONSUMER_LAG->"records";case HTTP_LATENCY_P95->"seconds";default->"per_second";};}
}
